void main()=>runApp(const KidsApp());
const burgundy=Color(0xFF6B1F2A), cream=Color(0xFFFFF8F5);

class Profile{
  String name; int stars,points; List<String> done,badges;
  Profile({required this.name,this.stars=0,this.points=0,List<String>? done,List<String>? badges}):done=done??[],badges=badges??[];
  int get level=>min(5,1+points~/100);
  String get levelName=>['المبتدئ','المتعلم','النجم الصغير','البطل','بطل المعرفة'][level-1];
  double get progress=>((points%100)/100).clamp(0.0,1.0).toDouble();
  void finish(String id){if(!done.contains(id))done.add(id);}
  void reward({int stars=0,int points=0}){this.stars+=stars;this.points+=points;if(this.points>=10&&!badges.contains('بداية جميلة'))badges.add('بداية جميلة');if(this.points>=100&&!badges.contains('نجم المعرفة'))badges.add('نجم المعرفة');if(this.stars>=10&&!badges.contains('جامع النجوم'))badges.add('جامع النجوم');}
  Map<String,dynamic> json()=>{'name':name,'stars':stars,'points':points,'done':done,'badges':badges};
  factory Profile.fromJson(Map<String,dynamic> j)=>Profile(name:j['name']??'طفلي',stars:j['stars']??0,points:j['points']??0,done:List<String>.from(j['done']??[]),badges:List<String>.from(j['badges']??[]));
}
class Store{
  static const key='profile';
  static Future<Profile?> load()async{final p=await SharedPreferences.getInstance();final s=p.getString(key);return s==null?null:Profile.fromJson(jsonDecode(s));}
  static Future<void> save(Profile p)async{final x=await SharedPreferences.getInstance();await x.setString(key,jsonEncode(p.json()));}
}
class Voice{static final t=FlutterTts();static Future<void> say(String s,{bool en=false})async{await t.setSpeechRate(.42);await t.setPitch(1.08);await t.setLanguage(en?'en-US':'ar-SA');await t.speak(s);}}

class KidsApp extends StatelessWidget{const KidsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'تعلّم وابتسم',theme:ThemeData(useMaterial3:true,colorSchemeSeed:burgundy),builder:(c,w)=>Directionality(textDirection:TextDirection.rtl,child:w!),home:const Start());}
class Start extends StatelessWidget{const Start({super.key});@override Widget build(BuildContext c)=>FutureBuilder<Profile?>(future:Store.load(),builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Scaffold(body:Center(child:CircularProgressIndicator()));return s.data==null?const Setup():Home(p:s.data!);});}

class Mascot extends StatelessWidget{final double size;const Mascot({super.key,this.size=120});@override Widget build(BuildContext c)=>SizedBox(width:size,height:size,child:CustomPaint(painter:MP()));}
class MP extends CustomPainter{@override void paint(Canvas c,Size s){final w=s.width,h=s.height;final skin=Paint()..color=const Color(0xFFFFD5B5),scarf=Paint()..color=Colors.green,dress=Paint()..color=Colors.amber,dark=Paint()..color=Colors.black87;c.drawPath(Path()..moveTo(w*.5,h*.42)..lineTo(w*.12,h)..lineTo(w*.88,h)..close(),dress);c.drawCircle(Offset(w*.5,h*.34),w*.23,skin);c.drawPath(Path()..moveTo(w*.5,h*.05)..quadraticBezierTo(w*.1,h*.12,w*.12,h*.58)..lineTo(w*.32,h*.58)..quadraticBezierTo(w*.3,h*.27,w*.5,h*.2)..quadraticBezierTo(w*.7,h*.27,w*.68,h*.58)..lineTo(w*.88,h*.58)..quadraticBezierTo(w*.9,h*.12,w*.5,h*.05)..close(),scarf);c.drawCircle(Offset(w*.42,h*.33),w*.025,dark);c.drawCircle(Offset(w*.58,h*.33),w*.025,dark);final sm=Path()..moveTo(w*.42,h*.42)..quadraticBezierTo(w*.5,h*.48,w*.58,h*.42);c.drawPath(sm,Paint()..color=dark.color..style=PaintingStyle.stroke..strokeWidth=2);}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}

class Setup extends StatefulWidget{const Setup({super.key});@override State<Setup> createState()=>_SetupState();}
