class Learn extends StatefulWidget{final Profile p;final String title,id;final List<String> items;final bool english;const Learn({super.key,required this.p,required this.title,required this.items,required this.english,required this.id});@override State<Learn> createState()=>_LearnState();}
class _LearnState extends State<Learn>{final seen=<int>{};bool awarded=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.title),backgroundColor:burgundy,foregroundColor:Colors.white),body:Column(children:[Padding(padding:const EdgeInsets.all(16),child:LinearProgressIndicator(value:seen.length/widget.items.length,minHeight:12)),Expanded(child:GridView.builder(padding:const EdgeInsets.all(16),gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:4,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:widget.items.length,itemBuilder:(c,i)=>InkWell(onTap:()async{await Voice.say(widget.items[i],en:widget.english);setState(()=>seen.add(i));if(seen.length==widget.items.length&&!awarded){awarded=true;widget.p.finish(widget.id);widget.p.reward(stars:1,points:10);await Store.save(widget.p);if(c.mounted)showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('ما شاء الله! 🌟'),content:const Text('أحسنت! حصلت على نجمة و10 نقاط.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('رائع!'))]));}},child:Container(decoration:BoxDecoration(color:seen.contains(i)?Colors.green.shade400:Colors.white,borderRadius:BorderRadius.circular(18),border:Border.all(color:burgundy,width:2)),child:Center(child:Text(widget.items[i],style:TextStyle(fontSize:28,fontWeight:FontWeight.bold,color:seen.contains(i)?Colors.white:burgundy)))))))]));}

class Game extends StatefulWidget{final Profile p;const Game({super.key,required this.p});@override State<Game> createState()=>_GameState();}
class _GameState extends State<Game>{final r=Random();final pool=['أ','ب','ت','ج','د','ر','س','م','ن','و'];String target='أ';List<String> choices=[];int score=0;bool locked=false;@override void initState(){super.initState();next();}void next(){target=pool[r.nextInt(pool.length)];choices={target,...List.generate(3,(_)=>pool[r.nextInt(pool.length)])}.toList()..shuffle();locked=false;}Future<void> pick(String x)async{if(locked)return;locked=true;if(x==target){score++;widget.p.reward(stars:1,points:10);await Store.save(widget.p);await Voice.say('أحسنت ما شاء الله');}else await Voice.say('حاول مرة أخرى');setState((){});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('صائد الحروف 🎮'),backgroundColor:burgundy,foregroundColor:Colors.white),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('اختر الحرف: $target',style:const TextStyle(fontSize:24,fontWeight:FontWeight.bold)),const SizedBox(height:25),Wrap(spacing:12,runSpacing:12,children:choices.map((x)=>SizedBox(width:130,height:75,child:FilledButton(onPressed:()=>pick(x),child:Text(x,style:const TextStyle(fontSize:30))))).toList()),const Spacer(),Text('النتيجة: $score ⭐',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:12),FilledButton.icon(onPressed:(){setState(next);},icon:const Icon(Icons.refresh),label:const Text('سؤال جديد'))])));}

